  "track.runtime.m.records.s.applyA.explain": "Từ lúc A được lấy, không ai khác đổi count ở global, nên không có xung đột. Thay đổi của A thành thay đổi của global một cách nguyên tử. Apply observer nhận tập {count}.",
  "track.runtime.m.records.ev.applyA": "a.apply(): thành công, global = {g}",
  "track.runtime.m.records.s.applyB.failed.title": "b.apply(): xung đột, thất bại",
  "track.runtime.m.records.s.applyB.failed.explain": "Lúc B được lấy, count là 0 (previous). Bây giờ global là 10 (current, do A). B muốn 20 (applied). `structuralEqualityPolicy.equivalent(10, 20)` là false, và `merge` mặc định trả null: không gộp được. Apply trả về Failure, thay đổi của B không vào global.",
  "track.runtime.m.records.ev.applyB.failed": "b.apply(): xung đột, thất bại",
  "track.runtime.m.records.s.applyB.merged.title": "b.apply(): xung đột, counterPolicy gộp thành 30",
  "track.runtime.m.records.s.applyB.merged.explain": "Vẫn là xung đột (previous 0, current 10, applied 20), nhưng `counterPolicy.merge` trả `current + (applied − previous)` = 10 + 20 = 30. Một record mới với giá trị gộp được ghi, apply thành công.",
  "track.runtime.m.records.ev.applyB.merged": "b.apply(): xung đột, counterPolicy gộp thành 30",
